('20000000-0000-0000-0000-000000000286', 'word_order', 10, '{"words": ["A", "good", "cover", "letter", "can", "make", "a", "big", "difference"], "correct_sentence": "A good cover letter can make a big difference", "translation": "Uma boa carta de apresentação pode fazer uma grande diferença"}'),
('20000000-0000-0000-0000-000000000286', 'reading', 11, '{"passage": "Before applying for a job, it helps to update your résumé and write a strong cover letter. Companies often receive applications from many applicants, so a clear résumé can make a real difference. If you are selected, the next step is usually an interview with the interviewer from human resources.", "translation": "Antes de se candidatar a uma vaga, ajuda atualizar o currículo e escrever uma boa carta de apresentação. As empresas costumam receber candidaturas de muitos candidatos, então um currículo claro pode fazer uma diferença real. Se você for selecionado, o próximo passo geralmente é uma entrevista com o entrevistador do RH.", "question": "What is usually the next step after being selected, according to the text?", "options": ["Writing a cover letter", "An interview", "Updating the résumé"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000286', 'listening', 12, '{"audio_text": "She applied for the marketing position. There were over fifty applicants for the job. The interview lasted about forty minutes.", "question": "How long did the interview last, according to the audio?", "options": ["Twenty minutes", "Forty minutes", "One hour"], "correct_index": 1}'),
