('20000000-0000-0000-0000-000000000286', 'typing', 14, '{"prompt_pt": "Traduza: ''Ela atualizou o currículo e se candidatou à vaga.''", "expected": "She updated her résumé and applied for the job.", "ai_review": true}'),

