('20000000-0000-0000-0000-000000000287', 'word_order', 9, '{"words": ["She", "has", "all", "the", "qualifications", "for", "the", "role"], "correct_sentence": "She has all the qualifications for the role", "translation": "Ela tem todas as qualificações para a função"}'),
('20000000-0000-0000-0000-000000000287', 'word_order', 10, '{"words": ["She", "has", "five", "years", "of", "experience", "in", "sales"], "correct_sentence": "She has five years of experience in sales", "translation": "Ela tem cinco anos de experiência em vendas"}'),
('20000000-0000-0000-0000-000000000287', 'reading', 11, '{"passage": "During an interview, it is common to be asked about your skills, your greatest strength, and even a weakness you are working on. Talking honestly about your experience and qualifications, along with a good recommendation, usually leaves a strong impression.", "translation": "Durante uma entrevista, é comum ser perguntado sobre suas habilidades, seu maior ponto forte e até um ponto fraco em que você está trabalhando. Falar com honestidade sobre sua experiência e qualificações, junto com uma boa recomendação, geralmente deixa uma impressão forte.", "question": "What usually leaves a strong impression, according to the text?", "options": ["Avoiding questions", "Talking honestly about experience and qualifications", "Hiding your weaknesses"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000287', 'listening', 12, '{"audio_text": "She has all the qualifications for the role. Communication is an important skill in this job. She has five years of experience in sales.", "question": "What skill is mentioned as important, according to the audio?", "options": ["Communication", "Negotiation", "Leadership"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000287', 'dictation', 13, '{"audio_text": "She has all the qualifications for the role.", "expected": "She has all the qualifications for the role."}'),
