('20000000-0000-0000-0000-000000000288', 'word_order', 10, '{"words": ["The", "recruiter", "contacted", "her", "on", "social", "media"], "correct_sentence": "The recruiter contacted her on social media", "translation": "O recrutador entrou em contato com ela nas redes sociais"}'),
('20000000-0000-0000-0000-000000000288', 'reading', 11, '{"passage": "When you receive a job offer, it usually includes a proposed salary and a list of benefits. Many people choose to negotiate before accepting, especially if the recruiter has already indicated they are eager to hire someone quickly.", "translation": "Quando você recebe uma oferta de emprego, ela geralmente inclui um salário proposto e uma lista de benefícios. Muitas pessoas escolhem negociar antes de aceitar, especialmente se o recrutador já indicou que está ansioso para contratar alguém rapidamente.", "question": "What do many people choose to do before accepting a job offer, according to the text?", "options": ["Resign immediately", "Negotiate", "Ignore the benefits"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000288', 'listening', 12, '{"audio_text": "She received a job offer from another company. They offered a competitive salary. It is normal to negotiate your starting salary.", "question": "What did the company offer, according to the audio?", "options": ["A promotion", "A competitive salary", "A probation period"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000288', 'dictation', 13, '{"audio_text": "They offered a competitive salary.", "expected": "They offered a competitive salary."}'),
